<?php
if(!defined('ABSPATH'))exit;
/** Human-approved bridge from locally generated Advisor recommendations to Intelligence Actions. */
function legacyx_ai_action_prepare(){if(!current_user_can('legacyx_manage_intelligence_actions'))wp_die('Access denied.');check_admin_referer('legacyx_ai_prepare_action');$note=isset($_GET['note'])?sanitize_text_field(wp_unslash($_GET['note'])):'';$client_id=isset($_GET['client_id'])?absint($_GET['client_id']):0;if(!$note)wp_die('No recommendation was supplied.');$token=wp_generate_password(20,false,false);set_transient('legacyx_ai_action_'.$token,array('user'=>get_current_user_id(),'note'=>$note,'client_id'=>$client_id),10*MINUTE_IN_SECONDS);wp_safe_redirect(add_query_arg(array('page'=>'legacyx-ai-advisor','prepare_action'=>$token),admin_url('admin.php')));exit;}add_action('admin_post_legacyx_ai_prepare_action','legacyx_ai_action_prepare');
function legacyx_ai_action_create(){if(!current_user_can('legacyx_manage_intelligence_actions'))wp_die('Access denied.');check_admin_referer('legacyx_ai_create_action');$token=sanitize_key(wp_unslash($_POST['token']??''));$draft=get_transient('legacyx_ai_action_'.$token);if(!$draft||intval($draft['user'])!==get_current_user_id())wp_die('This action draft has expired.');$title=sanitize_text_field(wp_unslash($_POST['action_title']??''));$priority=sanitize_text_field(wp_unslash($_POST['action_priority']??'Normal'));$due=sanitize_text_field(wp_unslash($_POST['action_due_date']??''));if(!$title)wp_die('Action title is required.');if(!in_array($priority,array('Normal','High','Critical'),true))$priority='Normal';$id=wp_insert_post(array('post_type'=>'legacyx_intel_action','post_status'=>'publish','post_title'=>$title));if(!$id||is_wp_error($id))wp_die('The management action could not be created.');update_post_meta($id,'_legacyx_client_profile_id',absint($draft['client_id']));update_post_meta($id,'_legacyx_action_status','Open');update_post_meta($id,'_legacyx_action_priority',$priority);update_post_meta($id,'_legacyx_action_due_date',$due);update_post_meta($id,'_legacyx_action_source','Legacy X AI Advisor · Human Approved');update_post_meta($id,'_legacyx_action_note',sanitize_textarea_field($draft['note']));update_post_meta($id,'_legacyx_ai_approved_by',get_current_user_id());update_post_meta($id,'_legacyx_ai_approved_at',current_time('mysql'));delete_transient('legacyx_ai_action_'.$token);wp_safe_redirect(add_query_arg(array('page'=>'legacyx-ai-advisor','action_created'=>$id),admin_url('admin.php')));exit;}add_action('admin_post_legacyx_ai_create_action','legacyx_ai_action_create');
function legacyx_ai_action_links($answer,$client_id=0){if(!current_user_can('legacyx_manage_intelligence_actions'))return '';ob_start();?><div class="lxa-action-bridge"><strong>Turn a recommendation into execution</strong><p>Select a recommendation below. Nothing is created until you review and approve the management action.</p><div><?php foreach(array_slice((array)$answer,0,4) as $line):$url=wp_nonce_url(add_query_arg(array('action'=>'legacyx_ai_prepare_action','note'=>$line,'client_id'=>absint($client_id)),admin_url('admin-post.php')),'legacyx_ai_prepare_action');?><a href="<?php echo esc_url($url);?>">Create Action from: <?php echo esc_html(wp_trim_words($line,12,'…'));?></a><?php endforeach;?></div></div><?php return ob_get_clean();}
function legacyx_ai_action_review(){if(!current_user_can('legacyx_manage_intelligence_actions'))return;$token=isset($_GET['prepare_action'])?sanitize_key(wp_unslash($_GET['prepare_action'])):'';if(!$token)return;$draft=get_transient('legacyx_ai_action_'.$token);if(!$draft||intval($draft['user'])!==get_current_user_id())return;$client=$draft['client_id']?get_the_title($draft['client_id']):'Firm-level';?><section class="lxa-action-review"><span>HUMAN APPROVAL REQUIRED</span><h2>Review Management Action</h2><p><strong>Context:</strong> <?php echo esc_html($client);?></p><blockquote><?php echo esc_html($draft['note']);?></blockquote><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="legacyx_ai_create_action"><input type="hidden" name="token" value="<?php echo esc_attr($token);?>"><?php wp_nonce_field('legacyx_ai_create_action');?><label>Action title<input required maxlength="160" name="action_title" value="<?php echo esc_attr(wp_trim_words($draft['note'],10,''));?>"></label><div><label>Priority<select name="action_priority"><option>Normal</option><option>High</option><option>Critical</option></select></label><label>Due date<input type="date" name="action_due_date"></label></div><button type="submit" class="button button-primary">Approve & Create Action</button><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=legacyx-ai-advisor'));?>">Cancel</a></form></section><?php }
function legacyx_ai_action_inject(){if(!current_user_can('legacyx_view_reports'))return;$screen=get_current_screen();if(!$screen||$screen->id!=='firm-os_page_legacyx-ai-advisor')return;if(isset($_GET['action_created'])){$id=absint($_GET['action_created']);if($id&&get_post_type($id)==='legacyx_intel_action')echo '<div class="notice notice-success"><p>Management action created. <a href="'.esc_url(get_edit_post_link($id)).'">Open Action →</a></p></div>';}
ob_start();legacyx_ai_action_review();$review=ob_get_clean();if($review)echo '<div id="lxa-action-review-source" style="display:none">'.$review.'</div><script>document.addEventListener("DOMContentLoaded",function(){var s=document.getElementById("lxa-action-review-source"),h=document.querySelector(".lxa-ai-hero");if(s&&h){var w=document.createElement("div");w.innerHTML=s.innerHTML;h.insertAdjacentElement("afterend",w.firstElementChild);s.remove();}});</script>';
if($_SERVER['REQUEST_METHOD']==='POST'&&!empty($_POST['legacyx_ai_question'])&&!empty($_POST['legacyx_ai_context_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_ai_context_nonce'])),'legacyx_ai_context')){$q=sanitize_text_field(wp_unslash($_POST['legacyx_ai_question']));$cid=absint($_POST['legacyx_ai_client']??0);$answer=legacyx_ai_context_answer($q,$cid);$links=legacyx_ai_action_links($answer,$cid);if($links)echo '<div id="lxa-action-links-source" style="display:none">'.$links.'</div><script>document.addEventListener("DOMContentLoaded",function(){var s=document.getElementById("lxa-action-links-source"),a=document.querySelector(".lxa-conv-answer");if(s&&a){var w=document.createElement("div");w.innerHTML=s.innerHTML;a.insertAdjacentElement("afterend",w.firstElementChild);s.remove();}});</script>';}}
add_action('admin_footer','legacyx_ai_action_inject',30);
function legacyx_ai_action_styles($hook){if($hook!=='firm-os_page_legacyx-ai-advisor')return;wp_register_style('legacyx-ai-actions',false);wp_enqueue_style('legacyx-ai-actions');$css='.lxa-action-bridge,.lxa-action-review{background:#fff;border:1px solid #ded8ce;padding:24px;margin-top:18px}.lxa-action-bridge>strong{font:22px Georgia,serif}.lxa-action-bridge>p{color:#706a62}.lxa-action-bridge>div{display:grid;gap:8px}.lxa-action-bridge a{padding:12px 14px;background:#f7f4ed;color:#171512;text-decoration:none;font-weight:700;border-left:3px solid #f05a16}.lxa-action-review>span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.lxa-action-review h2{font:29px Georgia,serif}.lxa-action-review blockquote{background:#f7f4ed;border-left:4px solid #f05a16;margin:18px 0;padding:16px}.lxa-action-review form>label,.lxa-action-review form>div{display:block;margin:14px 0}.lxa-action-review input,.lxa-action-review select{display:block;width:100%;max-width:620px;min-height:40px;margin-top:6px}.lxa-action-review form>div{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:620px}.lxa-action-review .button{margin-right:8px}@media(max-width:600px){.lxa-action-review form>div{grid-template-columns:1fr}}';wp_add_inline_style('legacyx-ai-actions',$css);}add_action('admin_enqueue_scripts','legacyx_ai_action_styles');
